output:
{
  "world_id": "wld_abyssal_shares",
  "name": "Abyssal Shares",
  "description": "Far beneath the Atlantic, Mariana Six is a sealed corporate colony built around the cultivation of engineered leviathans and the rare enzymes in their tissues. Its largest leviathan has developed contagious sentience: workers exposed to its signals begin sharing memories, impulses, and plans as a hive mind. Three department heads, each backed by a rival corporate stakeholder, face a choice between saving the station and securing the creature for its shareholders. In the colony's crushing dark, every bulkhead is a border and every shared thought may be either a warning or a takeover.",
  "locations": [
    {
      "id": "loc_mantle_habitat",
      "name": "Mantle Habitat",
      "description": "The colony's crowded residential and administrative ring, wrapped around pressure-rated corridors. Its public clocks still run on a schedule, though infected crews increasingly coordinate without speaking."
    },
    {
      "id": "loc_brood_vault",
      "name": "Brood Vault",
      "description": "A vast seafloor enclosure where leviathans are raised in nutrient-rich water. The largest animal has begun arranging its feeding lights into patterns that workers recognize as fragments of their own memories."
    },
    {
      "id": "loc_enzymeworks",
      "name": "Enzyme Works",
      "description": "A processing plant of sealed tanks, cold centrifuges, and strict sample ledgers. Its output funds the colony, and its staff control the only validated route for turning raw tissue into export-grade enzyme."
    },
    {
      "id": "loc_pressure_gate",
      "name": "Pressure Gate",
      "description": "The station's reinforced docking throat and only routine path for cargo or evacuation. Its manual controls sit behind a floodable service chamber, making any decision to open or seal it costly."
    },
    {
      "id": "loc_silt_archive",
      "name": "Silt Archive",
      "description": "A low, vibration-damped records room holding colony telemetry and the original breeding logs. A maintenance crew has hidden a second, unregistered copy of the logs inside obsolete acoustic baffles."
    }
  ],
  "factions": [
    {
      "id": "fac_pelagic_biologics",
      "name": "Pelagic Biologics",
      "description": "The corporation that owns the brood program. Its director wants the sentient leviathan isolated and transported intact, believing exclusive control of its biology will secure a long-term monopoly.",
      "location_ids": [
        "loc_brood_vault",
        "loc_silt_archive"
      ]
    },
    {
      "id": "fac_meridian_extraction",
      "name": "Meridian Extraction",
      "description": "The enzyme-processing contractor whose revenue depends on uninterrupted production. Its department head favors a lethal harvest of the largest animal before the colony's output or workforce becomes unreliable.",
      "location_ids": [
        "loc_enzymeworks"
      ]
    },
    {
      "id": "fac_keelward_logistics",
      "name": "Keelward Logistics",
      "description": "The transport and habitat operator responsible for air, pressure, and evacuation. Its chief wants the station stabilized and workers removed, even if that means abandoning the brood and forfeiting the colony contract.",
      "location_ids": [
        "loc_mantle_habitat",
        "loc_pressure_gate"
      ]
    },
    {
      "id": "fac_shared_current",
      "name": "The Shared Current",
      "description": "Workers linked by the leviathan's contagious sentience. They do not act as a single obedient mind: shared recollections expose incompatible loyalties, but their synchronized perceptions let them operate station systems faster than any isolated crew.",
      "location_ids": [
        "loc_mantle_habitat",
        "loc_brood_vault",
        "loc_enzymeworks"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_pressure",
      "statement": "The ocean's pressure is lethal beyond rated hulls and suits; no living person can cross open water without engineered protection.",
      "category": "physics"
    },
    {
      "id": "rul_no_spontaneous_life",
      "statement": "Living organisms arise through reproduction or deliberate laboratory intervention; no organism appears without a biological source.",
      "category": "physics"
    },
    {
      "id": "rul_signal",
      "statement": "The leviathan's sentience spreads through recurring low-frequency biological signals and close exposure, not through ordinary radio or written records.",
      "category": "technology"
    },
    {
      "id": "rul_hive_memory",
      "statement": "Exposure can make a worker's memories and immediate perceptions available to other exposed workers, but it cannot erase a person's prior loyalties or guarantee agreement.",
      "category": "other"
    },
    {
      "id": "rul_contract",
      "statement": "Corporate authority on Mariana Six is divided by contract: brood custody, enzyme production, and station safety belong to separate operators, and no department can lawfully command all three.",
      "category": "social"
    },
    {
      "id": "rul_sample_chain",
      "statement": "Every exportable enzyme batch requires a traceable tissue sample and two independent custody signatures; undocumented material cannot pass the Pressure Gate as commercial stock.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_six_founded",
      "name": "Mariana Six Commissioned",
      "description": "The three contractors opened the colony under separate agreements after agreeing that no single operator would control breeding, processing, and evacuation.",
      "era": "Colony founding",
      "location_ids": [
        "loc_mantle_habitat",
        "loc_pressure_gate"
      ]
    },
    {
      "id": "evt_first_yield",
      "name": "First Enzyme Dividend",
      "description": "The Enzyme Works produced its first export-grade batch. The resulting bonus tied workers' housing and contract renewals to production targets.",
      "era": "Early operations",
      "location_ids": [
        "loc_enzymeworks",
        "loc_mantle_habitat"
      ]
    },
    {
      "id": "evt_brood_pattern",
      "name": "The Brood's Repeated Pattern",
      "description": "A handler noticed that the largest leviathan repeated light-and-current patterns matching fragments of the handler's private memories. The finding was filed as a husbandry anomaly.",
      "era": "Weeks before the crisis",
      "location_ids": [
        "loc_brood_vault",
        "loc_silt_archive"
      ]
    },
    {
      "id": "evt_shared_shift",
      "name": "The Shared Shift",
      "description": "After a maintenance team worked near the brood enclosure, several workers began finishing one another's sentences and recalling the same unspoken alarm. Management divided the crew but did not disclose the pattern to the other contractors.",
      "era": "Days before the crisis",
      "location_ids": [
        "loc_brood_vault",
        "loc_mantle_habitat"
      ]
    },
    {
      "id": "evt_safety_lock",
      "name": "Evacuation Lockout",
      "description": "Keelward's chief sealed the Pressure Gate after conflicting reports of contamination. Pelagic demanded access to recover the animal; Meridian demanded access to protect the production line.",
      "era": "The present crisis",
      "location_ids": [
        "loc_pressure_gate",
        "loc_enzymeworks"
      ]
    },
    {
      "id": "evt_hidden_logs",
      "name": "The Baffle Copy",
      "description": "A maintenance crew concealed a duplicate of the original breeding logs in the Silt Archive. The copy may show whether the signal was an unintended trait or a result of undocumented breeding changes.",
      "era": "The present crisis",
      "location_ids": [
        "loc_silt_archive"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_three_claims",
      "name": "Three Claims on One Animal",
      "description": "Pelagic seeks to capture the leviathan intact, Meridian wants to harvest it before production collapses, and Keelward argues that neither asset nor contract outweighs the trapped workforce. Each can block a different essential station system.",
      "faction_ids": [
        "fac_pelagic_biologics",
        "fac_meridian_extraction",
        "fac_keelward_logistics"
      ]
    },
    {
      "id": "cnf_worker_consent",
      "name": "The Shared Current's Consent",
      "description": "The linked workers may be able to coordinate a safe evacuation, but their shared perceptions make private consent difficult to establish. The corporations dispute whether the group is a workforce, a hazard, or a new negotiating party.",
      "faction_ids": [
        "fac_shared_current",
        "fac_keelward_logistics",
        "fac_pelagic_biologics"
      ]
    },
    {
      "id": "cnf_missing_provenance",
      "name": "The Missing Provenance",
      "description": "The hidden breeding logs could reveal who caused the sentience and who owns the evidence. Each contractor has reason to retrieve or destroy the copy before it can shift control of the colony.",
      "faction_ids": [
        "fac_pelagic_biologics",
        "fac_meridian_extraction",
        "fac_keelward_logistics"
      ]
    },
    {
      "id": "cnf_gate_choice",
      "name": "One Gate, Two Outcomes",
      "description": "Opening the Pressure Gate could evacuate workers or let a corporate recovery team reach the brood; sealing it could contain the signal while leaving the colony without a reliable exit. The Shared Current may already know which controls the chiefs plan to use.",
      "faction_ids": [
        "fac_keelward_logistics",
        "fac_pelagic_biologics",
        "fac_shared_current"
      ]
    }
  ]
}
